module TopModule (
    input clk,
    input reset,
    output reg shift_ena
);
    reg [2:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            counter <= 3'd4;
            shift_ena <= 1'b1;
        end else if (counter > 3'd1) begin
            counter <= counter - 1'b1;
            shift_ena <= 1'b1;
        end else begin
            counter <= 3'd0;
            shift_ena <= 1'b0;
        end
    end
endmodule

