module tb_TopModule;
    reg clk;
    reg reset;
    wire shift_ena;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .shift_ena(shift_ena)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 0;
        #12;

        // Apply reset pulse
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        reset = 0;

        // Check that shift_ena is high for 4 cycles
        #1;
        // Cycle 1 after reset posedge
        $display("Time %0t: shift_ena = %b", $time, shift_ena);

        @(posedge clk); #1;
        $display("Time %0t: shift_ena = %b", $time, shift_ena);

        @(posedge clk); #1;
        $display("Time %0t: shift_ena = %b", $time, shift_ena);

        @(posedge clk); #1;
        $display("Time %0t: shift_ena = %b", $time, shift_ena);

        @(posedge clk); #1;
        $display("Time %0t: shift_ena = %b", $time, shift_ena);

        @(posedge clk); #1;
        $display("Time %0t: shift_ena = %b", $time, shift_ena);

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    reg clk;
    reg reset;
    wire shift_ena;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .shift_ena(shift_ena)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 0;
        #15;

        // Apply reset pulse
        @(posedge clk);
        reset <= 1;
        @(posedge clk);
        reset <= 0;

        // Cycle 1 (posedge where reset was sampled high)
        // shift_ena should be 1
        #1;
        if (shift_ena !== 1'b1) begin $display("SELFTEST FAIL: cycle 1 shift_ena is %b", shift_ena); $finish; end

        // Cycle 2
        @(posedge clk); #1;
        if (shift_ena !== 1'b1) begin $display("SELFTEST FAIL: cycle 2 shift_ena is %b", shift_ena); $finish; end

        // Cycle 3
        @(posedge clk); #1;
        if (shift_ena !== 1'b1) begin $display("SELFTEST FAIL: cycle 3 shift_ena is %b", shift_ena); $finish; end

        // Cycle 4
        @(posedge clk); #1;
        if (shift_ena !== 1'b1) begin $display("SELFTEST FAIL: cycle 4 shift_ena is %b", shift_ena); $finish; end

        // Cycle 5 (should be 0)
        @(posedge clk); #1;
        if (shift_ena !== 1'b0) begin $display("SELFTEST FAIL: cycle 5 shift_ena is %b", shift_ena); $finish; end

        // Cycle 6 (should remain 0)
        @(posedge clk); #1;
        if (shift_ena !== 1'b0) begin $display("SELFTEST FAIL: cycle 6 shift_ena is %b", shift_ena); $finish; end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
